import React from 'react';
import { FaMapMarkerAlt, FaPhone, FaStar, FaClock } from 'react-icons/fa';

const RideCard = ({ ride, onSelect, isPast = false }) => {
  const getStatusColor = (status) => {
    const colors = {
      searching: 'bg-yellow-100 text-yellow-800',
      accepted: 'bg-blue-100 text-blue-800',
      arriving: 'bg-blue-100 text-blue-800',
      started: 'bg-green-100 text-green-800',
      completed: 'bg-green-100 text-green-800',
      cancelled: 'bg-red-100 text-red-800',
    };
    return colors[status] || 'bg-gray-100 text-gray-800';
  };

  return (
    <div className="bg-white rounded-lg shadow-md p-4 mb-4 hover:shadow-lg transition">
      <div className="flex justify-between items-start mb-3">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-2">
            <FaMapMarkerAlt className="text-green-600" />
            <span className="text-sm text-gray-600">Pickup</span>
          </div>
          <p className="font-semibold text-gray-800">{ride.pickupAddress}</p>
        </div>
        <span className={`px-3 py-1 rounded-full text-sm font-medium ${getStatusColor(ride.rideStatus)}`}>
          {ride.rideStatus}
        </span>
      </div>

      <div className="flex items-center gap-2 mb-3 pl-6">
        <FaMapMarkerAlt className="text-red-600" />
        <span className="text-sm text-gray-600">Dropoff</span>
      </div>
      <p className="font-semibold text-gray-800 pl-6 mb-4">{ride.dropAddress}</p>

      <div className="grid grid-cols-3 gap-4 pt-3 border-t">
        <div>
          <p className="text-xs text-gray-500">Distance</p>
          <p className="font-semibold">{ride.estimatedDistance || ride.actualDistance || 0} km</p>
        </div>
        <div>
          <p className="text-xs text-gray-500">Fare</p>
          <p className="font-semibold">₹{ride.finalFare || ride.totalFare || 0}</p>
        </div>
        <div>
          <p className="text-xs text-gray-500">Time</p>
          <p className="font-semibold">{new Date(ride.createdAt).toLocaleDateString()}</p>
        </div>
      </div>

      {isPast && ride.userRating && (
        <div className="flex items-center gap-1 mt-3 p-2 bg-yellow-50 rounded">
          {[...Array(5)].map((_, i) => (
            <FaStar
              key={i}
              className={i < ride.userRating ? 'text-yellow-400' : 'text-gray-300'}
            />
          ))}
          <span className="ml-auto text-sm text-gray-600">{ride.userRating}/5</span>
        </div>
      )}

      {onSelect && (
        <button
          onClick={() => onSelect(ride)}
          className="w-full mt-4 bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 transition"
        >
          View Details
        </button>
      )}
    </div>
  );
};

export default RideCard;
